select p.oid::regprocedure::text as routine,pg_get_userbyid(p.proowner) as owner,p.prosecdef as security_definer,p.proconfig as configuration,encode(extensions.digest(pg_get_functiondef(p.oid),'sha256'),'hex') as definition_sha256,pg_get_functiondef(p.oid) as definition from pg_proc p where p.oid in (to_regprocedure('public.collection_is_public_approved(uuid)'),to_regprocedure('public.get_active_policy_document(text,text)'),to_regprocedure('public.list_account_request_reasons(text,text)'),to_regprocedure('public.public_collection_payment_route(uuid)'),to_regprocedure('public.user_can_read_collection(uuid,uuid)'),to_regprocedure('public.user_is_collection_admin(uuid,uuid)')) order by p.oid::regprocedure::text;
